using System.ComponentModel;
using System.Reflection;
namespace LadderRecords;
static class RecordsSettingsChecks
{
 public static void Run(Catalog catalog){void Check(bool value,string name){if(!value)throw new Exception(name);}var root=Path.Combine(AppContext.BaseDirectory,"test-data",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var settings=Path.Combine(root,"view.json");var store=new RecordStore(Path.Combine(root,"records.json"));var song=catalog.Songs.Single(s=>s.Name=="Fundamental");foreach(var judge in new[]{"노말","하드","맥스"})store.SetManual(new(song.Id,8,"SC",judge,0),judge=="노말"?99m:judge=="하드"?97m:98m,1);T Field<T>(RecordsDialog dialog,string name)=>(T)typeof(RecordsDialog).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(dialog)!;
  using(var dialog=new RecordsDialog(catalog,store,settings)){dialog.Show();Application.DoEvents();Field<ComboBox>(dialog,"judge").SelectedItem="하드·맥스";var grid=Field<RecordsView>(dialog,"grid");Check(grid.RowCount==2&&Enumerable.Range(0,2).All(i=>grid.ItemAt(i)!.Judge is "하드" or "맥스"),"Hard+max filter excludes normal and keeps both");Field<TextBox>(dialog,"search").Text="Fundamental";Field<ComboBox>(dialog,"button").SelectedItem="8B";Field<ComboBox>(dialog,"pattern").SelectedItem="SC";grid.Sort("Accuracy",ListSortDirection.Ascending);grid.Columns["Song"]!.Width=350;dialog.Size=new(1120,650);dialog.Close();}
  using(var restored=new RecordsDialog(catalog,store,settings)){restored.Show();Application.DoEvents();var grid=Field<RecordsView>(restored,"grid");Check(Field<TextBox>(restored,"search").Text=="Fundamental"&&Field<ComboBox>(restored,"button").Text=="8B"&&Field<ComboBox>(restored,"pattern").Text=="SC"&&Field<ComboBox>(restored,"judge").Text=="하드·맥스","Filters restored after new dialog construction");Check(grid.RowCount==2&&grid.ItemAt(0)!.Judge=="하드"&&grid.SortedColumn?.Name=="Accuracy"&&grid.SortOrder==SortOrder.Ascending,"Saved numeric sort restored");Check(grid.Columns["Song"]!.Width==350&&restored.Width==1120&&restored.Height==650,"Window and column sizes restored");Field<ComboBox>(restored,"judge").SelectedItem="전체";Check(grid.RowCount==3,"All judges still available");restored.Close();}
  File.WriteAllText(settings,"invalid json");Check(RecordsViewSettings.Load(settings).Judge=="전체","Damaged settings fallback");File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"records-settings-validation.txt"),"PASS: hard+max filter; normal exclusion; all judge option; search/button/pattern/judge persistence; numeric sort direction; window and column size; damaged settings fallback.");
 }
}
